content:
Below is an idiomatic Pulumi TypeScript `ComponentResource` that wraps:

- an **S3 bucket** with versioning, encryption, and public-access blocking
- an **RDS PostgreSQL instance** with deletion protection, backups, and private access
- an **IAM role for service accounts** with least-privilege policy support

It also supports **dev/prod via stack config**.

---

## Suggested file structure

```txt
.
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── index.ts
└── infra
    └── appPlatform.ts
```

---

## `infra/appPlatform.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppPlatformArgs {
    environment: "dev" | "prod";

    vpcId: pulumi.Input<string>;
    privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;
    dbSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * EKS OIDC provider ARN for IRSA trust.
     * Example: arn:aws:iam::<acct-id>:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/XXXX
     */
    oidcProviderArn: pulumi.Input<string>;

    /**
     * EKS OIDC issuer URL, without https:// removed is okay; we normalize it.
     * Example: https://oidc.eks.us-east-1.amazonaws.com/id/XXXX
     */
    oidcProviderUrl: pulumi.Input<string>;

    /**
     * Kubernetes service account identity for IRSA.
     */
    serviceAccountNamespace: pulumi.Input<string>;
    serviceAccountName: pulumi.Input<string>;

    dbName?: pulumi.Input<string>;
    dbUsername?: pulumi.Input<string>;

    /**
     * Store as Pulumi config secret in stack config.
     */
    dbPassword: pulumi.Input<string>;

    bucketReplicationRoleArn?: pulumi.Input<string>;
    replicationDestinationBucketArn?: pulumi.Input<string>;

    tags?: Record<string, pulumi.Input<string>>;
}

export class AppPlatform extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly bucketPublicAccessBlock: aws.s3.BucketPublicAccessBlock;
    public readonly dbSubnetGroup: aws.rds.SubnetGroup;
    public readonly dbInstance: aws.rds.Instance;
    public readonly iamRole: aws.iam.Role;
    public readonly dbConnectionString: pulumi.Output<string>;

    constructor(name: string, args: AppPlatformArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:infra:AppPlatform", name, {}, opts);

        const tags = {
            app: name,
            environment: args.environment,
            ...args.tags,
        };

        const isProd = args.environment === "prod";

        //
        // S3 bucket
        //
        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            tags,
        }, { parent: this });

        new aws.s3.BucketVersioningV2(`${name}-bucket-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-bucket-sse`, {
            bucket: this.bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "AES256",
                },
            }],
        }, { parent: this });

        this.bucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock(`${name}-bucket-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // Optional: prod cross-region replication if destination + role provided
        if (isProd && args.bucketReplicationRoleArn && args.replicationDestinationBucketArn) {
            new aws.s3.BucketReplicationConfig(`${name}-bucket-replication`, {
                bucket: this.bucket.id,
                role: args.bucketReplicationRoleArn,
                rules: [{
                    id: "replicate-to-us-west-2",
                    status: "Enabled",
                    destination: {
                        bucket: args.replicationDestinationBucketArn,
                    },
                }],
            }, { parent: this });
        }

        //
        // RDS PostgreSQL
        //
        this.dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.privateSubnetIds,
            tags,
        }, { parent: this });

        this.dbInstance = new aws.rds.Instance(`${name}-postgres`, {
            engine: "postgres",
            engineVersion: "15.4",
            instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
            allocatedStorage: isProd ? 100 : 20,
            maxAllocatedStorage: isProd ? 200 : 50,

            dbSubnetGroupName: this.dbSubnetGroup.name,
            vpcSecurityGroupIds: args.dbSecurityGroupIds,

            dbName: args.dbName ?? "appdb",
            username: args.dbUsername ?? "appuser",
            password: args.dbPassword,

            multiAz: isProd,
            storageEncrypted: true,
            backupRetentionPeriod: 7,
            deletionProtection: true,
            publiclyAccessible: false,
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${args.environment}-final-snapshot`,

            applyImmediately: true,
            tags,
        }, { parent: this });

        //
        // IAM role for service accounts (IRSA)
        //
        const oidcProviderUrlNormalized = pulumi.output(args.oidcProviderUrl).apply(url =>
            url.replace(/^https:\/\//, "")
        );

        const assumeRolePolicy = pulumi.all([
            args.oidcProviderArn,
            oidcProviderUrlNormalized,
            args.serviceAccountNamespace,
            args.serviceAccountName,
        ]).apply(([providerArn, providerUrl, namespace, saName]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Effect: "Allow",
                        Principal: {
                            Federated: providerArn,
                        },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${providerUrl}:sub`]: `system:serviceaccount:${namespace}:${saName}`,
                                [`${providerUrl}:aud`]: "sts.amazonaws.com",
                            },
                        },
                    },
                ],
            })
        );

        this.iamRole = new aws.iam.Role(`${name}-sa-role`, {
            assumeRolePolicy,
            tags,
        }, { parent: this });

        const rolePolicy = isProd
            ? JSON.stringify({
                  Version: "2012-10-17",
                  Statement: [
                      {
                          Effect: "Allow",
                          Action: [
                              "s3:GetObject",
                              "s3:PutObject",
                              "s3:DeleteObject",
                          ],
                          Resource: [
                              pulumi.interpolate`${this.bucket.arn}/*`,
                          ],
                      },
                      {
                          Effect: "Allow",
                          Action: [
                              "s3:ListBucket",
                          ],
                          Resource: [
                              this.bucket.arn,
                          ],
                      },
                  ],
              })
            : JSON.stringify({
                  Version: "2012-10-17",
                  Statement: [
                      {
                          Effect: "Allow",
                          Action: [
                              "s3:GetObject",
                              "s3:PutObject",
                              "s3:DeleteObject",
                              "s3:ListBucket",
                          ],
                          Resource: [
                              this.bucket.arn,
                              pulumi.interpolate`${this.bucket.arn}/*`,
                          ],
                      },
                  ],
              });

        new aws.iam.RolePolicy(`${name}-sa-policy`, {
            role: this.iamRole.id,
            policy: rolePolicy,
        }, { parent: this });

        this.dbConnectionString = pulumi.interpolate`postgresql://${args.dbUsername ?? "appuser"}:${args.dbPassword}@${this.dbInstance.address}:${this.dbInstance.port}/${args.dbName ?? "appdb"}`;

        this.registerOutputs({
            bucketName: this.bucket.bucket,
            bucketArn: this.bucket.arn,
            dbEndpoint: this.dbInstance.address,
            dbPort: this.dbInstance.port,
            iamRoleArn: this.iamRole.arn,
            dbConnectionString: this.dbConnectionString,
        });
    }
}
```

