## `index.ts`

This shows how to use stack config for `dev` and `prod`.

```ts
import * as pulumi from "@pulumi/pulumi";
import { AppPlatform } from "./infra/appPlatform";

const config = new pulumi.Config();
const stack = pulumi.getStack();

const environment = config.require("environment") as "dev" | "prod";

// Required network / cluster inputs from existing infra
const vpcId = config.require("vpcId");
const privateSubnetIds = config.requireObject<string[]>("privateSubnetIds");
const dbSecurityGroupIds = config.requireObject<string[]>("dbSecurityGroupIds");

const oidcProviderArn = config.require("oidcProviderArn");
const oidcProviderUrl = config.require("oidcProviderUrl");

const serviceAccountNamespace = config.get("serviceAccountNamespace") ?? "default";
const serviceAccountName = config.get("serviceAccountName") ?? "app";

const dbName = config.get("dbName") ?? "appdb";
const dbUsername = config.get("dbUsername") ?? "appuser";
const dbPassword = config.requireSecret("dbPassword");

// Optional prod replication config
const bucketReplicationRoleArn = config.get("bucketReplicationRoleArn");
const replicationDestinationBucketArn = config.get("replicationDestinationBucketArn");

const app = new AppPlatform(`web-${stack}`, {
    environment,
    vpcId,
    privateSubnetIds,
    dbSecurityGroupIds,
    oidcProviderArn,
    oidcProviderUrl,
    serviceAccountNamespace,
    serviceAccountName,
    dbName,
    dbUsername,
    dbPassword,
    bucketReplicationRoleArn,
    replicationDestinationBucketArn,
    tags: {
        project: pulumi.getProject(),
        stack,
    },
});

export const bucketName = app.bucket.bucket;
export const dbEndpoint = app.dbInstance.address;
export const iamRoleArn = app.iamRole.arn;
export const dbConnectionString = app.dbConnectionString;
```

